--!strict
local MarketplaceService=game:GetService("MarketplaceService");local RunService=game:GetService("RunService");local Config=require(game:GetService("ReplicatedStorage").Modules.MonetizationConfig);local Profiles=require(script.Parent.PlayerProfileService);local Service={}
local function findProduct(productId:number):(string?,any)for id,p in Config.Products do if p.ProductId==productId and productId~=0 then return id,p end end;return nil,nil end
function Service.GrantProduct(player:Player,id:string):boolean local product=Config.Products[id];if not product or not Profiles.IsProfileLoaded(player) then return false end;for key,amount in product.Grant do if key=="Coins" then Profiles.IncrementValue(player,"Economy.Coins",amount);Profiles.IncrementValue(player,"Economy.LifetimeCoins",amount) else Profiles.AddConsumable(player,key,amount) end end;Profiles.IncrementValue(player,"Monetization.TotalRobuxProductsGranted",1);return true end
function Service.DebugGrantProduct(player:Player,id:string):boolean if not RunService:IsStudio() then return false end;local ok=Service.GrantProduct(player,id);if ok then print(string.format("[DEBUG Monetization] granted %s to %s",id,player.Name)) end;return ok end
function Service.ProcessReceipt(info:any):Enum.ProductPurchaseDecision local player=game:GetService("Players"):GetPlayerByUserId(info.PlayerId);if not player or not Profiles.IsProfileLoaded(player) then return Enum.ProductPurchaseDecision.NotProcessedYet end;local profile=Profiles.GetProfile(player);local purchaseId=tostring(info.PurchaseId);if profile.Monetization.ProcessedReceipts[purchaseId] then return Profiles.SaveProfile(player,"receipt retry") and Enum.ProductPurchaseDecision.PurchaseGranted or Enum.ProductPurchaseDecision.NotProcessedYet end;local id=findProduct(info.ProductId);if not id or not Service.GrantProduct(player,id) then return Enum.ProductPurchaseDecision.NotProcessedYet end;profile.Monetization.ProcessedReceipts[purchaseId]=os.time();local entries={};for receipt,timestamp in profile.Monetization.ProcessedReceipts do table.insert(entries,{id=receipt,time=timestamp}) end;table.sort(entries,function(a,b)return a.time>b.time end);for i=Config.MaxProcessedReceipts+1,#entries do profile.Monetization.ProcessedReceipts[entries[i].id]=nil end;Profiles.MarkDirty(player);return Profiles.SaveProfile(player,"DeveloperProduct receipt") and Enum.ProductPurchaseDecision.PurchaseGranted or Enum.ProductPurchaseDecision.NotProcessedYet end
function Service.CheckPasses(player:Player) local profile=Profiles.GetProfile(player);if not profile then return end;for id,pass in Config.GamePasses do if pass.GamePassId~=0 then local ok,owns=pcall(MarketplaceService.UserOwnsGamePassAsync,MarketplaceService,player.UserId,pass.GamePassId);if ok then profile.Monetization.OwnedGamePasses[id]=owns==true end end end;Profiles.MarkDirty(player) end
return Service
